def calculate_factorial(n):
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer.")

    if n == 0:
        return 1
    else:
        result = 1
        for i in range(1, n + 1):
            result *= i
        return result

# Example usage:
if __name__ == "__main__":
    num1 = 5
    fact1 = calculate_factorial(num1)
    print(f"The factorial of {num1} is: {fact1}")

    num2 = 0
    fact2 = calculate_factorial(num2)
    print(f"The factorial of {num2} is: {fact2}")

    num3 = 7
    fact3 = calculate_factorial(num3)
    print(f"The factorial of {num3} is: {fact3}")

    try:
        calculate_factorial(-3)
    except ValueError as e:
        print(f"Error: {e}")

    try:
        calculate_factorial(3.5)
    except ValueError as e:
        print(f"Error: {e}")

