import re

def word_frequency(text):
    clean_text = re.sub(r'[^\w\s]', '', text)
    words = clean_text.lower().split()
    frequency = {}
    for word in words:
        if word:  # Ensure the word is not an empty string
            if word in frequency:
                frequency[word] += 1
            else:
                frequency[word] = 1
    return frequency

def main():
    sample_text = "Hello world, hello Python! Python is great. World of code."
    result = word_frequency(sample_text)
    print(f"Original text: '{sample_text}'")
    print(f"Word frequencies: {result}")

    another_text = "This is a test. A test, this is!"
    another_result = word_frequency(another_text)
    print(f"Original text: '{another_text}'")
    print(f"Word frequencies: {another_result}")

if __name__ == "__main__":
    main()

