import math

def geometric_mean(numbers):
    # Ensure all numbers are positive
    for num in numbers:
        if num <= 0:
            raise ValueError("All numbers in the list must be positive.")

    # Calculate the product of all numbers
    product = 1.0
    for num in numbers:
        product *= num

    # Calculate the Nth root
    n = len(numbers)
    if n == 0:
        raise ValueError("The list of numbers cannot be empty.")

    # Using math.pow for floating-point exponentiation
    # The Nth root of a number P is P raised to the power of (1/N)
    return math.pow(product, 1/n)

if __name__ == "__main__":
    # Test cases
    print(f"Geometric mean of [2, 8]: {geometric_mean([2, 8])}")
    print(f"Geometric mean of [1, 1, 1]: {geometric_mean([1, 1, 1])}")
    print(f"Geometric mean of [1, 2, 3, 4, 5]: {geometric_mean([1, 2, 3, 4, 5])}")
    print(f"Geometric mean of [10]: {geometric_mean([10])}")

    try:
        geometric_mean([])
    except ValueError as e:
        print(f"Error for empty list: {e}")

    try:
        geometric_mean([-2, 8])
    except ValueError as e:
        print(f"Error for negative number: {e}")

