def update_inventory(inventory, item_name, quantity):
    if item_name in inventory:
        inventory[item_name] += quantity
    else:
        inventory[item_name] = quantity
    return inventory

def test_update_inventory():
    # Test case 1: Item exists, add quantity
    initial_inventory_1 = {'apple': 10, 'orange': 5}
    updated_inventory_1 = update_inventory(initial_inventory_1, 'apple', 5)
    expected_inventory_1 = {'apple': 15, 'orange': 5}
    assert updated_inventory_1 == expected_inventory_1, f"Test Case 1 Failed: Expected {expected_inventory_1}, Got {updated_inventory_1}"

    # Test case 2: Item does not exist, add new item
    initial_inventory_2 = {'apple': 10}
    updated_inventory_2 = update_inventory(initial_inventory_2, 'banana', 3)
    expected_inventory_2 = {'apple': 10, 'banana': 3}
    assert updated_inventory_2 == expected_inventory_2, f"Test Case 2 Failed: Expected {expected_inventory_2}, Got {updated_inventory_2}"

    # Test case 3: Empty inventory, add new item
    initial_inventory_3 = {}
    updated_inventory_3 = update_inventory(initial_inventory_3, 'grape', 7)
    expected_inventory_3 = {'grape': 7}
    assert updated_inventory_3 == expected_inventory_3, f"Test Case 3 Failed: Expected {expected_inventory_3}, Got {updated_inventory_3}"

    # Test case 4: Item exists, add zero quantity
    initial_inventory_4 = {'pear': 20}
    updated_inventory_4 = update_inventory(initial_inventory_4, 'pear', 0)
    expected_inventory_4 = {'pear': 20}
    assert updated_inventory_4 == expected_inventory_4, f"Test Case 4 Failed: Expected {expected_inventory_4}, Got {updated_inventory_4}"

    # Test case 5: Item does not exist, add zero quantity
    initial_inventory_5 = {'kiwi': 1}
    updated_inventory_5 = update_inventory(initial_inventory_5, 'mango', 0)
    expected_inventory_5 = {'kiwi': 1, 'mango': 0}
    assert updated_inventory_5 == expected_inventory_5, f"Test Case 5 Failed: Expected {expected_inventory_5}, Got {updated_inventory_5}"

    print("All test cases passed!")

test_update_inventory()

