def multiplication_table(n):
    table = []
    for i in range(1, n + 1):
        row = []
        for j in range(1, n + 1):
            row.append(i * j)
        table.append(row)

    # Print the table to console for good measure
    print(f"Multiplication table up to {n}x{n}:")
    for row in table:
        row_str = " ".join(f"{x:4d}" for x in row)
        print(row_str)

    return table

