def decrypt_caesar(text, shift):
    decrypted_text = ""
    for char in text:
        if 'a' <= char <= 'z':
            start_ascii = ord('a')
            shifted_ascii = ord(char) - shift
            if shifted_ascii < start_ascii:
                shifted_ascii += 26
            decrypted_text += chr(shifted_ascii)
        else:
            decrypted_text += char
    return decrypted_text

