def is_valid_url(url: str) -> bool:
    if not isinstance(url, str):
        return False

    if url.startswith("http://") or url.startswith("https://"):
        scheme_end_index = url.find("://") + 3
        if scheme_end_index == 2:  # '://' not found
            return False

        remaining_part = url[scheme_end_index:]
        if "." in remaining_part:
            return True
        else:
            return False
    else:
        return False

