def harmonic_mean(numbers):
    if not numbers:
        raise ValueError("Input list cannot be empty.")

    sum_of_reciprocals = 0.0
    for number in numbers:
        if number <= 0:
            raise ValueError("All numbers must be positive.")
        sum_of_reciprocals += 1.0 / number

    n = len(numbers)
    arithmetic_mean_of_reciprocals = sum_of_reciprocals / n
    harmonic_mean_value = 1.0 / arithmetic_mean_of_reciprocals

    return harmonic_mean_value

