def count_keyword_occurrences(text, keyword):
    if not text or not keyword:
        return 0

    lower_text = text.lower()
    lower_keyword = keyword.lower()
    count = 0
    start_index = 0

    while True:
        found_index = lower_text.find(lower_keyword, start_index)
        if found_index == -1:
            break
        count += 1
        start_index = found_index + len(lower_keyword)
        if start_index >= len(lower_text):
            break
    return count

