def is_sorted(numbers):
    # An empty list or a list with one element is considered sorted
    if len(numbers) <= 1:
        return True

    # Iterate through the list, comparing each element with its successor
    for i in range(len(numbers) - 1):
        current_number = numbers[i]
        next_number = numbers[i+1]
        # If any element is greater than the next one, the list is not sorted
        if current_number > next_number:
            return False

    # If the loop completes, it means all elements were in ascending order
    return True

