from collections import Counter

def calculate_mode(numbers):
    if not numbers:
        return None

    # Count the frequency of each number in the list
    counts = Counter(numbers)

    # Find the maximum frequency
    max_frequency = 0
    for number, count in counts.items():
        if count > max_frequency:
            max_frequency = count

    # Iterate through the counts again to find a number with the max frequency
    # Since we can return any mode in case of a tie, the first one found is sufficient
    for number, count in counts.items():
        if count == max_frequency:
            return number

    # This part should ideally not be reached if numbers is not empty
    return None

