def hex_to_decimal(hex_string):
    decimal_value = 0
    power = 0
    for digit in reversed(hex_string):
        if '0' <= digit <= '9':
            digit_value = int(digit)
        elif 'A' <= digit <= 'F':
            digit_value = ord(digit) - ord('A') + 10
        elif 'a' <= digit <= 'f':
            digit_value = ord(digit) - ord('a') + 10
        else:
            # This case should not be reached given the problem description
            # but is included for robustness in a real-world scenario.
            raise ValueError("Invalid hexadecimal digit found")
        decimal_value += digit_value * (16 ** power)
        power += 1
    return decimal_value

