def is_palindromic_number(number):
    if number < 0:
        return False
    original_number = number
    reversed_number = 0
    while number > 0:
        digit = number % 10
        reversed_number = reversed_number * 10 + digit
        number //= 10
    if original_number == reversed_number:
        return True
    else:
        return False

