def encrypt_shift(text, shift):
    """
    Encrypts a string using a simple shift cipher.

    Args:
        text (str): The input string to encrypt.
        shift (int): The number of positions to shift each letter.

    Returns:
        str: The encrypted string.
    """
    result = []
    for char in text:
        if 'a' <= char <= 'z':
            shifted_char_code = ord('a') + (ord(char) - ord('a') + shift) % 26
            result.append(chr(shifted_char_code))
        elif 'A' <= char <= 'Z':
            shifted_char_code = ord('A') + (ord(char) - ord('A') + shift) % 26
            result.append(chr(shifted_char_code))
        else:
            result.append(char)
    return "".join(result)

