def longest_common_prefix(strings):
    if not strings:
        return ""

    # Sort the array of strings. The common prefix must be a prefix of
    # both the first and the last string in the sorted array.
    strings.sort()

    first_string = strings[0]
    last_string = strings[-1]

    common_prefix_length = 0
    min_len = min(len(first_string), len(last_string))

    for i in range(min_len):
        if first_string[i] == last_string[i]:
            common_prefix_length += 1
        else:
            break

    return first_string[:common_prefix_length]

