def is_valid_ipv4(ip_address: str) -> bool:
    parts = ip_address.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        if not part.isdigit():
            return False

        num = int(part)
        if not (0 <= num <= 255):
            return False

        # Check for leading zeros, e.g., '01' is invalid
        if len(part) > 1 and part[0] == '0':
            return False

    return True

