import math

def mean_absolute_deviation(numbers):
    if not numbers:
        return 0.0

    n = len(numbers)
    if n == 0:
        return 0.0

    total_sum = 0.0
    for number in numbers:
        total_sum += number

    mean = total_sum / n

    absolute_deviations_sum = 0.0
    for number in numbers:
        absolute_deviations_sum += abs(number - mean)

    mad = absolute_deviations_sum / n
    return mad

