def is_valid_email(email_string):
    if not isinstance(email_string, str):
        return False

    at_count = email_string.count('@')
    if at_count != 1:
        return False

    parts = email_string.split('@')
    local_part = parts[0]
    domain_part = parts[1]

    if not local_part:
        return False
    if not domain_part:
        return False

    if '.' not in domain_part:
        return False

    # Further checks for domain part, ensuring dot is not at the beginning or end
    if domain_part.startswith('.') or domain_part.endswith('.'):
        return False

    return True

