def word_frequency(words):
    frequency_map = {}
    if not words:
        return frequency_map

    for word in words:
        normalized_word = word.lower()
        if normalized_word in frequency_map:
            frequency_map[normalized_word] += 1
        else:
            frequency_map[normalized_word] = 1

    return frequency_map

