def simple_hash(s):
    total_ascii_sum = 0
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    for char_code in s:
        total_ascii_sum += ord(char_code)
    return total_ascii_sum

def test_simple_hash():
    assert simple_hash('cat') == 312
    assert simple_hash('') == 0
    assert simple_hash('hello') == 532
    assert simple_hash('a') == 97
    assert simple_hash('A') == 65
    assert simple_hash('123') == 150
    try:
        simple_hash(123)
        assert False, "TypeError was not raised for non-string input"
    except TypeError:
        pass
    print("All tests passed!")

if __name__ == '__main__':
    test_simple_hash()

